const body = $input.first().json.body || $input.first().json;
const data = body.data || {};
const message = data.message || {};
const key = data.key || {};

if (body.event !== 'messages.upsert') {
  return [{ json: { skip: true, reason: 'not_upsert' } }];
}
if (key.fromMe) {
  return [{ json: { skip: true, reason: 'own_message' } }];
}
const remoteJid = key.remoteJid || '';
if (remoteJid.includes('@g.us')) {
  return [{ json: { skip: true, reason: 'group' } }];
}

const phoneNumber = remoteJid.replace('@s.whatsapp.net', '');
const instance = body.instance || '';

let messageType = 'other';
let textContent = '';
let locationLat = null;
let locationLng = null;
let selectedCategory = null;

if (message.conversation || message.extendedTextMessage) {
  messageType = 'text';
  textContent = (message.conversation || message.extendedTextMessage?.text || '').trim();
} else if (message.locationMessage || message.liveLocationMessage) {
  messageType = 'location';
  const loc = message.locationMessage || message.liveLocationMessage;
  locationLat = loc.degreesLatitude;
  locationLng = loc.degreesLongitude;
} else if (message.listResponseMessage) {
  messageType = 'listResponse';
  selectedCategory = message.listResponseMessage.singleSelectReply?.selectedRowId || '';
} else if (message.buttonsResponseMessage) {
  messageType = 'text';
  textContent = message.buttonsResponseMessage.selectedButtonId || '';
}

return [{ json: {
  skip: false, messageType, phoneNumber, remoteJid,
  instance, textContent, locationLat, locationLng, selectedCategory
} }];

const { phoneNumber, remoteJid, instance, locationLat: lat, locationLng: lng } = $json;

const sd = $getWorkflowStaticData('global');
sd.sessions = sd.sessions || {};
sd.sessions[phoneNumber] = {
  state: 'has_location', lat, lng, city: null,
  updatedAt: new Date().toISOString()
};

const listPayload = {
  number: remoteJid,
  listMessage: {
    title: 'وين تبغى تروح؟ 🗺️',
    description: 'استلمت موقعك ✅\nاختر نوع المكان:',
    buttonText: 'اعرض الخيارات ↓',
    footerText: 'وين أروح • بحث ذكي',
    sections: [
      {
        title: '🍽️ طعام وشراب',
        rows: [
          { rowId: 'restaurant', title: '🍽️ مطعم', description: 'أقرب مطاعم حولك' },
          { rowId: 'cafe', title: '☕ مقهى / كافيه', description: 'أقرب مقاهي' },
          { rowId: 'bakery', title: '🥖 مخبز / حلويات', description: 'أقرب مخابز' }
        ]
      },
      {
        title: '💊 صحة وطوارئ',
        rows: [
          { rowId: 'pharmacy', title: '💊 صيدلية', description: 'أقرب صيدلية' },
          { rowId: 'hospital', title: '🏥 مستشفى / عيادة', description: 'أقرب مستشفى' }
        ]
      },
      {
        title: '🛍️ خدمات يومية',
        rows: [
          { rowId: 'supermarket', title: '🛒 بقالة / سوبرماركت', description: 'أقرب بقالة' },
          { rowId: 'gas_station', title: '⛽ محطة بنزين', description: 'أقرب محطة' },
          { rowId: 'atm', title: '🏧 صراف آلي', description: 'أقرب صراف' }
        ]
      },
      {
        title: '🕌 أخرى',
        rows: [
          { rowId: 'mosque', title: '🕌 مسجد', description: 'أقرب مسجد' },
          { rowId: 'park', title: '🌳 حديقة / منتزه', description: 'أقرب حديقة' },
          { rowId: 'lodging', title: '🏨 فندق / استراحة', description: 'أقرب فندق' }
        ]
      }
    ]
  }
};

return [{ json: { remoteJid, instance, listPayload } }];

const { phoneNumber, remoteJid, instance, selectedCategory } = $json;

const sd = $getWorkflowStaticData('global');
const session = (sd.sessions || {})[phoneNumber] || {};

if (!session.lat || !session.lng) {
  return [{ json: {
    action: 'no_location',
    remoteJid, instance,
    replyText: 'عذراً، انتهت جلستك. أرسل موقعك مجدداً 📍'
  } }];
}

return [{ json: {
  action: 'search',
  remoteJid, instance, phoneNumber,
  lat: session.lat, lng: session.lng,
  placeType: selectedCategory,
  radius: session.city ? 5000 : 2000,
  city: session.city || null
} }];

const { phoneNumber, remoteJid, instance, textContent: text } = $json;

const CITIES = {
  'رياض': {lat:24.7136,lng:46.6753,name:'الرياض'},
  'الرياض': {lat:24.7136,lng:46.6753,name:'الرياض'},
  'جدة': {lat:21.4858,lng:39.1925,name:'جدة'},
