  'كويت': {lat:29.3759,lng:47.9774,name:'الكويت'},
  'الكويت': {lat:29.3759,lng:47.9774,name:'الكويت'},
  'دبي': {lat:25.2048,lng:55.2708,name:'دبي'},
  'أبوظبي': {lat:24.4539,lng:54.3773,name:'أبوظبي'},
  'ابوظبي': {lat:24.4539,lng:54.3773,name:'أبوظبي'},
  'الشارقة': {lat:25.3463,lng:55.4209,name:'الشارقة'},
  'طريف': {lat:30.6607,lng:38.7283,name:'طريف'},
  'حائل': {lat:27.5219,lng:41.7057,name:'حائل'},
  'تبوك': {lat:28.3998,lng:36.5714,name:'تبوك'},
  'أبها': {lat:18.2164,lng:42.5053,name:'أبها'}
};

const sd = $getWorkflowStaticData('global');
const sessions = sd.sessions || {};
const session = sessions[phoneNumber] || { state: 'idle' };

// كشف اسم المدينة
const cityMatch = CITIES[text] || CITIES[text.replace(/^ال/, '')];
if (cityMatch) {
  sessions[phoneNumber] = {
    state: 'has_location',
    lat: cityMatch.lat, lng: cityMatch.lng,
    city: cityMatch.name,
    updatedAt: new Date().toISOString()
  };
  sd.sessions = sessions;
  return [{ json: {
    action: 'send_list', remoteJid, instance,
    cityName: cityMatch.name,
    listDescription: `📍 بحث في: *${cityMatch.name}*\nاختر نوع المكان:`
  } }];
}

// لا يوجد موقع → ترحيب
if (!session.lat || !session.lng) {
  return [{ json: { action: 'send_welcome', remoteJid, instance } }];
}

// يوجد موقع + نص → كشف النية
return [{ json: {
  action: 'call_intent',
  remoteJid, instance, phoneNumber,
  text,
  lat: session.lat, lng: session.lng,
  radius: session.city ? 5000 : 2000,
  city: session.city || null
} }];

