const intent = $json;
const ctx = $('Handle Text').first().json;

if (!intent.place_type) {
  // لم يُكتشف نوع المكان → أعِد إرسال القائمة
  return [{ json: {
    action: 'send_list',
    remoteJid: ctx.remoteJid,
    instance: ctx.instance,
    listDescription: 'لم أفهم ما تبحث عنه 😅\nاختر من القائمة:'
  } }];
}

return [{ json: {
  action: 'search',
  remoteJid: ctx.remoteJid,
  instance: ctx.instance,
  phoneNumber: ctx.phoneNumber,
  lat: ctx.lat,
  lng: ctx.lng,
  placeType: intent.place_type,
  radius: ctx.radius || 2000,
  city: ctx.city || null
} }];

// يستقبل من: Handle List Response
const d = $json;
return [{ json: {
  remoteJid: d.remoteJid,
  instance: d.instance,
  phoneNumber: d.phoneNumber,
  searchBody: {
    lat: d.lat,
    lng: d.lng,
    place_type: d.placeType,
    radius: d.radius || 2000,
    max_results: 5,
    phone_number: d.phoneNumber
  }
} }];

const result = $json;

// جلب remoteJid و instance من أي مصدر متاح
let remoteJid, instance;
try { remoteJid = $('Build Search Payload').first().json.remoteJid; } catch(_) {}
try { instance = $('Build Search Payload').first().json.instance; } catch(_) {}
if (!remoteJid) {
  try { remoteJid = $('Prepare Text Search').first().json.remoteJid; } catch(_) {}
  try { instance = $('Prepare Text Search').first().json.instance; } catch(_) {}
}

const message = result.formatted_message ||
  'عذراً، لم أجد نتائج قريبة. جرّب نوعاً آخر أو موقعاً مختلفاً.';

return [{ json: { remoteJid, instance, message } }];
